Smallest correct fix: keep the signature stagnationT(mach) so nothing that calls it changes, and replace the body with log-log interpolation of an equilibrium-air table at sea-level stagnation pressure (p ≈ ρ0·v²):

```js
// Equilibrium-air stagnation temperature (K), sea-level freestream, p_stag ≈ rho0*v^2.
// Gibbs-minimisation table (N2,O2,NO,N,O, ions to bare nuclei, RRHO); reproduces Anderson's
// 11 km/s / 1 atm shock-layer value (~11,600 K) to 2%. Radiative losses ignored (upper bound).
const STAG_EQ = [[1000,767],[1500,1309],[2000,2004],[3000,3614],[4000,5166],[5000,7011],[7000,9836],
  [10000,14060],[15000,27313],[20000,40530],[30000,74044],[50000,136822],[80000,2.296e5],
  [120000,5.68e5],[200000,1.137e6],[400000,5.854e6],[1e6,4.136e7],[3e6,3.77e8]];
function stagnationT(mach) {
  const v = mach * K.a0;
  if (v <= 1000) return K.T0 * (1 + 0.5 * (K.gammaAir - 1) * mach * mach); // within 3% here
  let i = 1; while (i < STAG_EQ.length - 1 && v > STAG_EQ[i][0]) i++;
  const [v1, T1] = STAG_EQ[i - 1], [v2, T2] = STAG_EQ[i];
  return T1 * Math.pow(T2 / T1, Math.log(v / v1) / Math.log(v2 / v1));
}
```

